import React, { useState } from 'react';
import { useQuery, useMutation, gql } from '@apollo/client';
import AddUserModal from './AddUserModal';
import EditUserModal from './EditUserModal';
import './UsersView.css';

const USERS_QUERY = gql`
  query Users {
    users {
      id
      username
      email
      role
      scopes
    }
  }
`;

const DELETE_USER_MUTATION = gql`
  mutation DeleteUser($id: ID!) {
    deleteUser(id: $id)
  }
`;

const UsersView = () => {
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingUser, setEditingUser] = useState(null);
  const { loading, error, data, refetch } = useQuery(USERS_QUERY);
  const [deleteUser] = useMutation(DELETE_USER_MUTATION, {
    onCompleted: () => {
      refetch();
    },
  });

  const handleDelete = (userId, username) => {
    if (window.confirm(`Are you sure you want to delete user "${username}"?`)) {
      deleteUser({
        variables: { id: userId },
        onError: (err) => {
          alert(err.message || 'Failed to delete user');
        },
      });
    }
  };

  const handleEdit = (user) => {
    setEditingUser(user);
  };

  const handleCloseModals = () => {
    setShowAddModal(false);
    setEditingUser(null);
    refetch();
  };

  if (loading) {
    return (
      <div className="users-loading">
        <div className="loading-spinner"></div>
        <p>Loading users...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="users-error">
        <p>Error loading users: {error.message}</p>
        <button onClick={() => refetch()}>Retry</button>
      </div>
    );
  }

  const users = data?.users || [];

  return (
    <div className="users-view">
      <div className="users-header">
        <div>
          <h2>User Management</h2>
          <span className="user-count">({users.length} users)</span>
        </div>
        <button className="add-user-button" onClick={() => setShowAddModal(true)}>
          + Add User
        </button>
      </div>

      {users.length === 0 ? (
        <div className="users-empty">
          <div style={{ fontSize: '48px', marginBottom: '16px' }}>👥</div>
          <h3>No Users Yet</h3>
          <p>Get started by creating your first user.</p>
          <button
            className="add-user-button"
            onClick={() => setShowAddModal(true)}
            style={{ marginTop: '20px' }}
          >
            + Create First User
          </button>
        </div>
      ) : (
        <div className="users-grid">
          {users.map((user) => (
            <div key={user.id} className="user-card">
              <div className="user-card-header">
                <div className="user-avatar-large">
                  {user.username.charAt(0).toUpperCase()}
                </div>
                <div className="user-info">
                  <h3>{user.username}</h3>
                  <p className="user-email">{user.email}</p>
                </div>
                <span className={`user-role-badge ${user.role.toLowerCase()}`}>
                  {user.role}
                </span>
              </div>
              {user.scopes && user.scopes.length > 0 && (
                <div className="user-scopes">
                  <strong>Scopes:</strong>
                  <div className="scopes-list">
                    {user.scopes.map((scope, idx) => (
                      <span key={idx} className="scope-tag">
                        {scope.replace(/_/g, ' ')}
                      </span>
                    ))}
                  </div>
                </div>
              )}
              {user.role === 'ADMIN' && (
                <div className="user-scopes">
                  <span className="scope-note-admin">⚡ Full Access (All Scopes)</span>
                </div>
              )}
              <div className="user-card-actions">
                <button
                  className="edit-button"
                  onClick={() => handleEdit(user)}
                  title="Edit User"
                >
                  ✏️ Edit
                </button>
                <button
                  className="delete-button"
                  onClick={() => handleDelete(user.id, user.username)}
                  title="Delete User"
                >
                  🗑️ Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {showAddModal && (
        <AddUserModal
          onClose={handleCloseModals}
          onSuccess={handleCloseModals}
        />
      )}

      {editingUser && (
        <EditUserModal
          user={editingUser}
          onClose={handleCloseModals}
          onSuccess={handleCloseModals}
        />
      )}
    </div>
  );
};

export default UsersView;
